INSERT OR IGNORE INTO setlist_items VALUES (28478, 4, 51, 'encore_2', 'song', '顽固', 'NULL', 'NULL', 'NULL', '2026-06-19 19:56:23', '2026-06-19 19:56:23');
INSERT OR IGNORE INTO setlist_items VALUES (28479, 4, 52, 'encore_2', 'talking', 'Talking', '[阿信]当年，在写出了倔强之后，又过了10年，不同的年纪不同的心境，我又写下了一首属于我们40岁的倔强，这首歌《顽固》，一起唱吧……\\n[阿信]继续come on\\n[阿信]如果这不是演唱会，那么这是一台时间上最伟大的时光机。我们不需要最华丽的舞台，我们不需要最灿烂的灯光，不需要特效，甚至不需要所有那些让我们忘记最初的最美好的事物。我只需要那些遗落在岁月中的歌曲，我只需要台上我的几位好哥们，我只需要、只需要你……', 'NULL', '阿信Talking', '2026-06-19 19:56:23', '2026-06-19 19:56:23');
