INSERT OR IGNORE INTO setlist_items VALUES (25672, 9, 46, 'encore_2', 'talking', 'Talking', '[阿信]唱完了，今天就结束了。\\n[全场观众]不要\\n[阿信]要不然大家从头开始，一起帮我把最后一句拖得很长很长很长很长，拖过了午夜，拖过了天亮，让我们一起看到——明天的太阳。', 'NULL', '战歌Talking', '2026-05-29 23:26:32', '2026-05-29 23:26:32');
