INSERT OR IGNORE INTO setlist_items VALUES (27686, 14, 29, 'request', 'song', '不见不散', 'NULL', 'NULL', 'NULL', '2026-06-17 16:47:09', '2026-06-17 16:47:09');
INSERT OR IGNORE INTO setlist_items VALUES (27687, 14, 30, 'main', 'talking', 'Talking', '[阿信]确实是，不见不散。结束了这轮的演唱会之后，最想和你们说的，就是在最近的未来，要和你们，不见不散。约好了哦，好吗？\\n[全场观众]好！\\n[阿信]到时候，我希望你们，带着你人生新的故事、新的展开、新的生活，来到这里，再让我，再看到你们，好吗？\\n[全场观众]好！\\n[阿信]如果我们要再度相认的话，那么，请你拿出手机，点亮属于你的那颗星星。让我看到你的光亮，你的名字，你的一切。\\n[阿信]接下来这首歌，我希望能够再度的听到你们的声音，让我，带回家，带回未来暂时看不到你的日子里面，带回我人生最美最美的自传里。知足。', 'NULL', '阿信Talking', '2026-06-17 16:47:09', '2026-06-17 16:47:09');
